public class IteratorUtils_collatedIterator_TriageGen0Test {

    @Test
    public void testCollatedIteratorWithIntegers() {
        Comparator<Integer> comparator = Integer::compare;
        Iterator<Integer> iter1 = Arrays.asList(1, 3, 5).iterator();
        Iterator<Integer> iter2 = Arrays.asList(2, 4, 6).iterator();

        Iterator<Integer> result = IteratorUtils.collatedIterator(comparator, iter1, iter2);

        List<Integer> expected = Arrays.asList(1, 2, 3, 4, 5, 6);
        List<Integer> actual = IteratorUtils.toList(result);

        assertEquals("The collated iterator should return elements in sorted order", expected, actual);
    }

    @Test
    public void testCollatedIteratorWithUnevenLengths() {
        Comparator<Integer> comparator = Integer::compare;
        Iterator<Integer> iter1 = Arrays.asList(1, 10).iterator();
        Iterator<Integer> iter2 = Arrays.asList(2, 5, 8).iterator();

        Iterator<Integer> result = IteratorUtils.collatedIterator(comparator, iter1, iter2);

        List<Integer> expected = Arrays.asList(1, 2, 5, 8, 10);
        List<Integer> actual = IteratorUtils.toList(result);

        assertEquals("The collated iterator should handle iterators of different lengths", expected, actual);
    }

    @Test
    public void testCollatedIteratorWithEmptyIterators() {
        Comparator<String> comparator = String::compareTo;
        Iterator<String> iter1 = Collections.emptyIterator();
        Iterator<String> iter2 = Arrays.asList("a", "c").iterator();

        Iterator<String> result = IteratorUtils.collatedIterator(comparator, iter1, iter2);

        List<String> expected = Arrays.asList("a", "c");
        List<String> actual = IteratorUtils.toList(result);

        assertEquals("The collated iterator should work when one iterator is empty", expected, actual);
    }

    @Test
    public void testCollatedIteratorWithBothEmpty() {
        Comparator<Integer> comparator = Integer::compare;
        Iterator<Integer> iter1 = Collections.emptyIterator();
        Iterator<Integer> iter2 = Collections.emptyIterator();

        Iterator<Integer> result = IteratorUtils.collatedIterator(comparator, iter1, iter2);

        assertFalse("The iterator should be empty", result.hasNext());
    }

    @Test
    public void testCollatedIteratorWithStrings() {
        Comparator<String> comparator = String::compareTo;
        Iterator<String> iter1 = Arrays.asList("apple", "cherry").iterator();
        Iterator<String> iter2 = Arrays.asList("banana", "date").iterator();

        Iterator<String> result = IteratorUtils.collatedIterator(comparator, iter1, iter2);

        List<String> expected = Arrays.asList("apple", "banana", "cherry", "date");
        List<String> actual = IteratorUtils.toList(result);

        assertEquals("The collated iterator should work with Strings", expected, actual);
    }

    @Test
    public void testCollatedIteratorWithDuplicates() {
        Comparator<Integer> comparator = Integer::compare;
        Iterator<Integer> iter1 = Arrays.asList(1, 2, 2).iterator();
        Iterator<Integer> iter2 = Arrays.asList(2, 3).iterator();

        Iterator<Integer> result = IteratorUtils.collatedIterator(comparator, iter1, iter2);

        List<Integer> expected = Arrays.asList(1, 2, 2, 2, 3);
        List<Integer> actual = IteratorUtils.toList(result);

        assertEquals("The collated iterator should handle duplicate values correctly", expected, actual);
    }
